#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char** divideString(char* s, int k, char fill, int* returnSize) {
    int n = (int)strlen(s);
    int groups = (n + k - 1) / k;
    char** result = (char**)malloc((size_t)groups * sizeof(char*));
    for (int i = 0; i < groups; ++i) {
        int start = i * k;
        int len = n - start;
        if (len > k) len = k;
        result[i] = (char*)malloc((size_t)k + 1);
        memcpy(result[i], s + start, (size_t)len);
        for (int j = len; j < k; ++j) result[i][j] = fill;
        result[i][k] = '\0';
    }
    *returnSize = groups;
    return result;
}

